    /**
     * Filter the query on the CONSECUTIVO_ID column
     *
     * Example usage:
     * <code>
     * $query->filterByConsecutivoId(1234); // WHERE CONSECUTIVO_ID = 1234
     * $query->filterByConsecutivoId(array(12, 34)); // WHERE CONSECUTIVO_ID IN (12, 34)
     * $query->filterByConsecutivoId(array('min' => 12)); // WHERE CONSECUTIVO_ID >= 12
     * $query->filterByConsecutivoId(array('max' => 12)); // WHERE CONSECUTIVO_ID <= 12
     * </code>
     *
     * @param     mixed $consecutivoId The value to use as filter.
     *              Use scalar values for equality.
     *              Use array values for in_array() equivalent.
     *              Use associative array('min' => $minValue, 'max' => $maxValue) for intervals.
     * @param     string $comparison Operator to use for the column comparison, defaults to Criteria::EQUAL
     *
     * @return AuditLogQuery The current query, for fluid interface
     */
    public function filterByConsecutivoId($consecutivoId = null, $comparison = null)
    {
        if (is_array($consecutivoId)) {
            $useMinMax = false;
            if (isset($consecutivoId['min'])) {
                $this->addUsingAlias(AuditLogPeer::CONSECUTIVO_ID, $consecutivoId['min'], Criteria::GREATER_EQUAL);
                $useMinMax = true;
            }
            if (isset($consecutivoId['max'])) {
                $this->addUsingAlias(AuditLogPeer::CONSECUTIVO_ID, $consecutivoId['max'], Criteria::LESS_EQUAL);
                $useMinMax = true;
            }
            if ($useMinMax) {
                return $this;
            }
            if (null === $comparison) {
                $comparison = Criteria::IN;
            }
        }

        return $this->addUsingAlias(AuditLogPeer::CONSECUTIVO_ID, $consecutivoId, $comparison);
    }

